    // Все строки интерфейса. Порядок языков: ru, en, uk, de, es, pt, tr, pl
    static class Loc
    {
        public static readonly string[] Codes = { "ru", "en", "uk", "de", "es", "pt", "tr", "pl" };
        public static readonly string[] Names = { "Русский", "English", "Українська", "Deutsch", "Español", "Português", "Türkçe", "Polski" };
        static readonly string[] Cultures = { "ru-RU", "en-US", "uk-UA", "de-DE", "es-ES", "pt-BR", "tr-TR", "pl-PL" };
        public static int Lang = 1;
        static readonly Dictionary<string, string[]> D = new Dictionary<string, string[]>();
        static CultureInfo culture;

        public static CultureInfo Culture
        {
            get
            {
                if (culture == null || culture.Name != Cultures[Lang])
                {
                    try { culture = new CultureInfo(Cultures[Lang]); } catch { culture = CultureInfo.InvariantCulture; }
                }
                return culture;
            }
        }

        public static void Init()
        {
            // По умолчанию английский; язык, выбранный пользователем в меню, запоминается
            string saved = AppInfo.GetSetting("Lang");
            int i = saved == null ? -1 : Array.IndexOf(Codes, saved);
            Lang = i >= 0 ? i : 1;
        }

        public static bool Has(string key) { return D.ContainsKey(key); }
        public static IEnumerable<string> Keys { get { return D.Keys; } }
        public static int Count(string key) { string[] v; return D.TryGetValue(key, out v) ? v.Length : 0; }

        public static string T(string key)
        {
            string[] v;
            if (!D.TryGetValue(key, out v)) return key;
            if (Lang < v.Length && !string.IsNullOrEmpty(v[Lang])) return v[Lang];
            return v.Length > 1 ? v[1] : v[0];
        }

        public static string F(string key, params object[] args)
        {
            try { return string.Format(Culture, T(key), args); } catch { return T(key); }
        }

        static void A(string key, params string[] v) { D[key] = v; }

