            A("diag.hz.ok", @"{0} Гц — это максимум для текущего разрешения.", @"{0} Hz — the maximum for the current resolution.", @"{0} Гц — максимум для поточної роздільної здатності.", @"{0} Hz — das Maximum für die aktuelle Auflösung.", @"{0} Hz: el máximo para la resolución actual.", @"{0} Hz — o máximo para a resolução atual.", @"{0} Hz — mevcut çözünürlük için en yüksek değer.", @"{0} Hz — maksimum dla bieżącej rozdzielczości.");
            A("diag.hz.warn", @"Монитор работает на {0} Гц, а поддерживает {1} Гц. Включите максимум в параметрах дисплея — в играх будет плавнее.", @"Your monitor runs at {0} Hz but supports {1} Hz. Set the maximum in display settings — games will feel smoother.", @"Монітор працює на {0} Гц, а підтримує {1} Гц. Увімкніть максимум у параметрах дисплея — в іграх буде плавніше.", @"Der Bildschirm läuft mit {0} Hz, unterstützt aber {1} Hz. Stellen Sie in den Anzeigeeinstellungen das Maximum ein — Spiele laufen flüssiger.", @"El monitor funciona a {0} Hz pero admite {1} Hz. Pon el máximo en la configuración de pantalla: los juegos se verán más fluidos.", @"O monitor está em {0} Hz, mas suporta {1} Hz. Ajuste o máximo nas configurações de vídeo — os jogos ficarão mais fluidos.", @"Monitörünüz {0} Hz'de çalışıyor ama {1} Hz'i destekliyor. Ekran ayarlarında en yükseğe alın — oyunlar daha akıcı olur.", @"Monitor działa z częstotliwością {0} Hz, a obsługuje {1} Hz. Ustaw maksimum w ustawieniach ekranu — gry będą płynniejsze.");
            A("diag.disk.t", @"Свободное место на диске {0}", @"Free space on drive {0}", @"Вільне місце на диску {0}", @"Freier Speicher auf Laufwerk {0}", @"Espacio libre en el disco {0}", @"Espaço livre no disco {0}", @"{0} sürücüsünde boş alan", @"Wolne miejsce na dysku {0}");
            A("diag.disk.ok", @"Свободно {0} ({1} %).", @"{0} free ({1}%).", @"Вільно {0} ({1} %).", @"{0} frei ({1} %).", @"{0} libres ({1} %).", @"{0} livres ({1}%).", @"{0} boş (%{1}).", @"Wolne {0} ({1}%).");
            A("diag.disk.warn", @"Осталось {0} ({1} %). Когда места мало, Windows и игры начинают тормозить — освободите место.", @"Only {0} left ({1}%). When space runs low, Windows and games slow down — free some up.", @"Залишилося {0} ({1} %). Коли місця мало, Windows та ігри гальмують — звільніть місце.", @"Nur noch {0} frei ({1} %). Bei wenig Speicher werden Windows und Spiele langsamer — schaffen Sie Platz.", @"Quedan {0} ({1} %). Con poco espacio, Windows y los juegos se ralentizan: libera espacio.", @"Restam {0} ({1}%). Com pouco espaço, o Windows e os jogos ficam lentos — libere espaço.", @"Yalnızca {0} kaldı (%{1}). Alan azaldığında Windows ve oyunlar yavaşlar — yer açın.", @"Zostało {0} ({1}%). Gdy brakuje miejsca, Windows i gry zwalniają — zwolnij miejsce.");
            A("diag.reboot.t", @"Ожидает перезагрузки", @"Restart pending", @"Очікує перезавантаження", @"Neustart ausstehend", @"Reinicio pendiente", @"Reinicialização pendente", @"Yeniden başlatma bekleniyor", @"Oczekuje na ponowne uruchomienie");
            A("diag.reboot.warn", @"Windows установила обновления и ждёт перезагрузки. До неё обновления могут работать в фоне и мешать играм.", @"Windows installed updates and is waiting for a restart. Until then, updates may keep working in the background and get in the way of games.", @"Windows встановила оновлення й чекає перезавантаження. До нього оновлення можуть працювати у фоні й заважати іграм.", @"Windows hat Updates installiert und wartet auf einen Neustart. Bis dahin können Updates im Hintergrund laufen und Spiele stören.", @"Windows instaló actualizaciones y espera un reinicio. Hasta entonces pueden seguir trabajando en segundo plano y molestar en los juegos.", @"O Windows instalou atualizações e aguarda reinicialização. Até lá, elas podem rodar em segundo plano e atrapalhar os jogos.", @"Windows güncellemeleri yükledi ve yeniden başlatmayı bekliyor. O zamana kadar güncellemeler arka planda çalışıp oyunları etkileyebilir.", @"Windows zainstalował aktualizacje i czeka na ponowne uruchomienie. Do tego czasu mogą działać w tle i przeszkadzać w grach.");
            A("diag.hags.t", @"Аппаратное планирование GPU", @"Hardware-accelerated GPU scheduling", @"Апаратне планування GPU", @"Hardwarebeschleunigte GPU-Planung", @"Programación de GPU acelerada por hardware", @"Agendamento de GPU acelerado por hardware", @"Donanım hızlandırmalı GPU zamanlaması", @"Sprzętowo akcelerowane planowanie GPU");
            A("diag.hags.off", @"Выключено. На современных видеокартах его обычно включают — это может немного снизить задержку. Решать вам.", @"Off. It's usually turned on for modern graphics cards — it may slightly reduce latency. Your call.", @"Вимкнено. На сучасних відеокартах його зазвичай вмикають — це може трохи зменшити затримку. Вирішувати вам.", @"Aus. Bei modernen Grafikkarten wird es meist eingeschaltet — das kann die Latenz etwas senken. Ihre Entscheidung.", @"Desactivada. En tarjetas modernas suele activarse: puede reducir un poco la latencia. Tú decides.", @"Desligado. Em placas modernas costuma ser ligado — pode reduzir um pouco a latência. A decisão é sua.", @"Kapalı. Modern ekran kartlarında genelde açılır — gecikmeyi biraz azaltabilir. Karar sizin.", @"Wyłączone. Na nowoczesnych kartach zwykle się je włącza — może nieco zmniejszyć opóźnienie. Decyzja należy do ciebie.");
            A("diag.hags.on", @"Включено.", @"On.", @"Увімкнено.", @"Ein.", @"Activada.", @"Ligado.", @"Açık.", @"Włączone.");
            A("diag.startup.t", @"Автозагрузка", @"Startup apps", @"Автозавантаження", @"Autostart", @"Inicio automático", @"Inicialização", @"Başlangıç uygulamaları", @"Autostart");
            A("diag.startup.ok", @"Вместе с Windows запускается программ: {0}.", @"Apps that start with Windows: {0}.", @"Разом із Windows запускається програм: {0}.", @"Apps, die mit Windows starten: {0}.", @"Aplicaciones que se inician con Windows: {0}.", @"Aplicativos que iniciam com o Windows: {0}.", @"Windows ile başlayan uygulama sayısı: {0}.", @"Z Windows uruchamia się programów: {0}.");
            A("diag.startup.many", @"Вместе с Windows запускается программ: {0}. Лишние замедляют включение ПК и висят в фоне — отключите ненужные.", @"Apps that start with Windows: {0}. Extra ones slow down boot and stay in the background — turn off the ones you don't need.", @"Разом із Windows запускається програм: {0}. Зайві сповільнюють увімкнення ПК і висять у фоні — вимкніть непотрібні.", @"Apps, die mit Windows starten: {0}. Überflüssige verlangsamen den Start und laufen im Hintergrund — deaktivieren Sie unnötige.", @"Aplicaciones que se inician con Windows: {0}. Las que sobran ralentizan el arranque y quedan en segundo plano: desactiva las que no uses.", @"Aplicativos que iniciam com o Windows: {0}. Os desnecessários deixam a inicialização lenta e ficam em segundo plano — desative os que não usa.", @"Windows ile başlayan uygulama sayısı: {0}. Fazlası açılışı yavaşlatır ve arka planda kalır — gereksizleri kapatın.", @"Z Windows uruchamia się programów: {0}. Zbędne spowalniają start i działają w tle — wyłącz niepotrzebne.");
            A("act.display", @"Открыть параметры дисплея", @"Open display settings", @"Відкрити параметри дисплея", @"Anzeigeeinstellungen öffnen", @"Abrir configuración de pantalla", @"Abrir configurações de vídeo", @"Ekran ayarlarını aç", @"Otwórz ustawienia ekranu");
            A("act.clean", @"Перейти к очистке", @"Go to Cleanup", @"Перейти до очищення", @"Zur Bereinigung", @"Ir a Limpieza", @"Ir para Limpeza", @"Temizliğe git", @"Przejdź do czyszczenia");
            A("act.graphics", @"Открыть настройки графики", @"Open graphics settings", @"Відкрити налаштування графіки", @"Grafikeinstellungen öffnen", @"Abrir configuración de gráficos", @"Abrir configurações de gráficos", @"Grafik ayarlarını aç", @"Otwórz ustawienia grafiki");
            A("act.startup", @"Открыть автозагрузку", @"Open startup apps", @"Відкрити автозавантаження", @"Autostart öffnen", @"Abrir aplicaciones de inicio", @"Abrir aplicativos de inicialização", @"Başlangıç uygulamalarını aç", @"Otwórz autostart");

            // --- Настройка ---
            A("tw.title", @"Настройка", @"Tweaks", @"Налаштування", @"Einstellungen", @"Ajustes", @"Ajustes", @"Ayarlar", @"Ustawienia");
            A("tw.sub", @"Включайте и выключайте изменения по одному. Выключение возвращает прежнее значение.", @"Turn changes on or off one by one. Turning one off restores the previous value.", @"Вмикайте й вимикайте зміни по одній. Вимкнення повертає попереднє значення.", @"Schalten Sie Änderungen einzeln ein oder aus. Ausschalten stellt den vorherigen Wert wieder her.", @"Activa o desactiva los cambios uno a uno. Al desactivarlo se restaura el valor anterior.", @"Ligue ou desligue as alterações uma a uma. Desligar restaura o valor anterior.", @"Değişiklikleri tek tek açıp kapatın. Kapatmak önceki değeri geri getirir.", @"Włączaj i wyłączaj zmiany pojedynczo. Wyłączenie przywraca poprzednią wartość.");
            A("pr.rec", @"Рекомендуемые", @"Recommended", @"Рекомендовані", @"Empfohlen", @"Recomendados", @"Recomendados", @"Önerilenler", @"Zalecane");
            A("pr.games", @"Для игр", @"For gaming", @"Для ігор", @"Für Spiele", @"Para juegos", @"Para jogos", @"Oyun için", @"Do gier");
            A("pr.resp", @"Отзывчивость", @"Responsiveness", @"Чуйність", @"Reaktionsfähigkeit", @"Respuesta", @"Responsividade", @"Duyarlılık", @"Responsywność");
            A("pr.none", @"Всё выключить", @"Turn all off", @"Вимкнути все", @"Alles aus", @"Desactivar todo", @"Desligar tudo", @"Tümünü kapat", @"Wyłącz wszystko");
            A("grp.power", @"Питание", @"Power", @"Живлення", @"Energie", @"Energía", @"Energia", @"Güç", @"Zasilanie");
            A("grp.gpu", @"Графика", @"Graphics", @"Графіка", @"Grafik", @"Gráficos", @"Gráficos", @"Grafik", @"Grafika");
