            A("grp.resp", @"Отзывчивость", @"Responsiveness", @"Чуйність", @"Reaktionsfähigkeit", @"Capacidad de respuesta", @"Responsividade", @"Duyarlılık", @"Responsywność");
            A("grp.input", @"Мышь", @"Mouse", @"Миша", @"Maus", @"Ratón", @"Mouse", @"Fare", @"Mysz");
            A("grp.sys", @"Система", @"System", @"Система", @"System", @"Sistema", @"Sistema", @"Sistem", @"System");
            A("risk.low", @"Риск: низкий", @"Risk: low", @"Ризик: низький", @"Risiko: gering", @"Riesgo: bajo", @"Risco: baixo", @"Risk: düşük", @"Ryzyko: niskie");
            A("risk.none", @"Без риска", @"No risk", @"Без ризику", @"Ohne Risiko", @"Sin riesgo", @"Sem risco", @"Risksiz", @"Bez ryzyka");
            A("tag.admin", @"нужны права администратора", @"needs admin rights", @"потрібні права адміністратора", @"Adminrechte nötig", @"requiere administrador", @"requer administrador", @"yönetici izni gerekir", @"wymaga administratora");
            A("tag.restart", @"после перезагрузки", @"after restart", @"після перезавантаження", @"nach Neustart", @"tras reiniciar", @"após reiniciar", @"yeniden başlatmadan sonra", @"po restarcie");
            A("tw.pending", @"Изменений к применению: {0}", @"Changes to apply: {0}", @"Змін до застосування: {0}", @"Ausstehende Änderungen: {0}", @"Cambios por aplicar: {0}", @"Alterações a aplicar: {0}", @"Uygulanacak değişiklik: {0}", @"Zmian do zastosowania: {0}");
            A("tw.noPending", @"Изменений нет", @"No changes", @"Змін немає", @"Keine Änderungen", @"Sin cambios", @"Sem alterações", @"Değişiklik yok", @"Brak zmian");
            A("tw.apply", @"Применить изменения", @"Apply changes", @"Застосувати зміни", @"Änderungen anwenden", @"Aplicar cambios", @"Aplicar alterações", @"Değişiklikleri uygula", @"Zastosuj zmiany");
            A("tw.reset", @"Отменить", @"Discard", @"Скасувати", @"Verwerfen", @"Descartar", @"Descartar", @"Vazgeç", @"Odrzuć");

            A("tw.power-plan.t", @"Схема питания «Высокая производительность»", @"“High performance” power plan", @"Схема живлення «Висока продуктивність»", @"Energiesparplan „Höchstleistung“", @"Plan de energía «Alto rendimiento»", @"Plano de energia “Alto desempenho”", @"“Yüksek performans” güç planı", @"Plan zasilania „Wysoka wydajność”");
            A("tw.power-plan.d", @"Процессор не сбрасывает частоту и не паркует ядра — ровнее кадры и отзывчивее ввод. На ноутбуке от батареи расход выше.", @"The CPU doesn't drop its clock or park cores — steadier frame times and snappier input. On a laptop on battery, power use goes up.", @"Процесор не скидає частоту й не паркує ядра — рівніші кадри та чуйніше введення. На ноутбуці від батареї витрата вища.", @"Die CPU senkt den Takt nicht und parkt keine Kerne — gleichmäßigere Frametimes und direktere Eingaben. Am Laptop im Akkubetrieb steigt der Verbrauch.", @"La CPU no baja la frecuencia ni aparca núcleos: fotogramas más estables y respuesta más rápida. En un portátil con batería, el consumo sube.", @"A CPU não reduz a frequência nem estaciona núcleos — quadros mais estáveis e resposta mais rápida. Em notebook na bateria, o consumo aumenta.", @"İşlemci frekansı düşürmez ve çekirdekleri park etmez — daha dengeli kare süreleri ve daha hızlı tepki. Pilde çalışan dizüstünde tüketim artar.", @"Procesor nie obniża taktowania i nie parkuje rdzeni — równiejsze klatki i szybsza reakcja. Na laptopie na baterii zużycie rośnie.");
            A("tw.game-dvr.t", @"Отключить запись Xbox Game Bar", @"Turn off Xbox Game Bar recording", @"Вимкнути запис Xbox Game Bar", @"Xbox Game Bar-Aufnahme ausschalten", @"Desactivar la grabación de Xbox Game Bar", @"Desligar a gravação do Xbox Game Bar", @"Xbox Game Bar kaydını kapat", @"Wyłącz nagrywanie Xbox Game Bar");
            A("tw.game-dvr.d", @"Выключает запись клипов и фоновую запись — меньше лишней нагрузки на видеокарту. Сам Game Bar продолжит работать.", @"Turns off clip and background recording — less extra load on the GPU. Game Bar itself keeps working.", @"Вимикає запис кліпів і фоновий запис — менше зайвого навантаження на відеокарту. Сам Game Bar працюватиме далі.", @"Deaktiviert Clip- und Hintergrundaufnahme — weniger Zusatzlast für die Grafikkarte. Die Game Bar selbst funktioniert weiter.", @"Desactiva la grabación de clips y en segundo plano: menos carga extra en la GPU. Game Bar sigue funcionando.", @"Desliga a gravação de clipes e em segundo plano — menos carga extra na placa de vídeo. O Game Bar continua funcionando.", @"Klip ve arka plan kaydını kapatır — ekran kartında daha az ek yük. Game Bar çalışmaya devam eder.", @"Wyłącza nagrywanie klipów i w tle — mniej dodatkowego obciążenia GPU. Sam Game Bar nadal działa.");
            A("tw.flip-vrr.t", @"Оптимизация оконных игр и VRR", @"Optimizations for windowed games and VRR", @"Оптимізація віконних ігор і VRR", @"Optimierungen für Spiele im Fenstermodus und VRR", @"Optimizaciones para juegos en ventana y VRR", @"Otimizações para jogos em janela e VRR", @"Pencereli oyun optimizasyonları ve VRR", @"Optymalizacje gier w oknie i VRR");
            A("tw.flip-vrr.d", @"Игры в окне и без рамки используют быстрый вывод кадров как в полноэкранном режиме, а на мониторе с G-Sync/FreeSync включается переменная частота.", @"Windowed and borderless games use the fast presentation path of fullscreen, and variable refresh rate works on G-Sync/FreeSync monitors.", @"Ігри у вікні та без рамки використовують швидкий вивід кадрів як у повноекранному режимі, а на моніторі з G-Sync/FreeSync вмикається змінна частота.", @"Spiele im Fenster und randlos nutzen die schnelle Bildausgabe wie im Vollbild, und auf G-Sync/FreeSync-Monitoren wird variable Bildrate aktiviert.", @"Los juegos en ventana y sin bordes usan la salida rápida de la pantalla completa, y en monitores G-Sync/FreeSync se activa la frecuencia variable.", @"Jogos em janela e sem borda usam a apresentação rápida da tela cheia, e a taxa variável funciona em monitores G-Sync/FreeSync.", @"Pencereli ve çerçevesiz oyunlar tam ekrandaki hızlı kare sunumunu kullanır; G-Sync/FreeSync monitörlerde değişken yenileme hızı açılır.", @"Gry w oknie i bez ramki korzystają z szybkiego wyświetlania jak na pełnym ekranie, a na monitorach G-Sync/FreeSync działa zmienna częstotliwość.");
            A("tw.vrr.t", @"VRR для оконных игр", @"VRR for windowed games", @"VRR для віконних ігор", @"VRR für Spiele im Fenstermodus", @"VRR para juegos en ventana", @"VRR para jogos em janela", @"Pencereli oyunlar için VRR", @"VRR dla gier w oknie");
            A("tw.vrr.d", @"На мониторе с G-Sync/FreeSync переменная частота работает и в играх в окне.", @"On G-Sync/FreeSync monitors, variable refresh rate also works for windowed games.", @"На моніторі з G-Sync/FreeSync змінна частота працює й в іграх у вікні.", @"Auf G-Sync/FreeSync-Monitoren funktioniert die variable Bildrate auch in Spielen im Fenster.", @"En monitores G-Sync/FreeSync, la frecuencia variable también funciona en juegos en ventana.", @"Em monitores G-Sync/FreeSync, a taxa variável também funciona em jogos em janela.", @"G-Sync/FreeSync monitörlerde değişken yenileme hızı pencereli oyunlarda da çalışır.", @"Na monitorach G-Sync/FreeSync zmienna częstotliwość działa też w grach w oknie.");
            A("tw.game-mode.t", @"Игровой режим Windows", @"Windows Game Mode", @"Ігровий режим Windows", @"Windows-Spielmodus", @"Modo de juego de Windows", @"Modo de Jogo do Windows", @"Windows Oyun Modu", @"Tryb gry Windows");
            A("tw.game-mode.d", @"Windows отдаёт приоритет игре и не ставит драйверы и обновления, пока вы играете.", @"Windows prioritizes the game and holds off driver installs and updates while you play.", @"Windows надає пріоритет грі й не встановлює драйвери та оновлення, поки ви граєте.", @"Windows priorisiert das Spiel und installiert während des Spielens keine Treiber und Updates.", @"Windows da prioridad al juego y no instala controladores ni actualizaciones mientras juegas.", @"O Windows prioriza o jogo e não instala drivers nem atualizações enquanto você joga.", @"Windows oyuna öncelik verir ve siz oynarken sürücü ve güncelleme yüklemez.", @"Windows nadaje priorytet grze i nie instaluje sterowników ani aktualizacji, gdy grasz.");
            A("tw.net-throttling.t", @"Отключить сетевой троттлинг", @"Turn off network throttling", @"Вимкнути мережевий тротлінг", @"Netzwerkdrosselung deaktivieren", @"Desactivar la limitación de red", @"Desligar a limitação de rede", @"Ağ kısıtlamasını kapat", @"Wyłącz dławienie sieci");
            A("tw.net-throttling.d", @"Windows перестаёт ограничивать сетевые пакеты, когда играет звук или голосовой чат.", @"Windows stops limiting network packets while audio or voice chat is playing.", @"Windows перестає обмежувати мережеві пакети, коли грає звук або голосовий чат.", @"Windows begrenzt keine Netzwerkpakete mehr, während Audio oder Sprachchat läuft.", @"Windows deja de limitar los paquetes de red mientras suena audio o un chat de voz.", @"O Windows deixa de limitar pacotes de rede enquanto há áudio ou chat de voz.", @"Ses veya sesli sohbet çalarken Windows ağ paketlerini sınırlamayı bırakır.", @"Windows przestaje ograniczać pakiety sieciowe, gdy gra dźwięk lub czat głosowy.");
            A("tw.nic-power.t", @"Отключить энергосбережение сетевой карты", @"Turn off network adapter power saving", @"Вимкнути енергозбереження мережевої карти", @"Energiesparen des Netzwerkadapters deaktivieren", @"Desactivar el ahorro de energía del adaptador de red", @"Desligar a economia de energia do adaptador de rede", @"Ağ bağdaştırıcısı güç tasarrufunu kapat", @"Wyłącz oszczędzanie energii karty sieciowej");
            A("tw.nic-power.d", @"Сетевая карта не засыпает — меньше скачков пинга. Только физические адаптеры, без виртуальных и VPN.", @"The network adapter doesn't go to sleep — fewer ping spikes. Physical adapters only, no virtual or VPN ones.", @"Мережева карта не засинає — менше стрибків пінгу. Лише фізичні адаптери, без віртуальних і VPN.", @"Der Netzwerkadapter geht nicht in den Ruhezustand — weniger Ping-Spitzen. Nur physische Adapter, keine virtuellen oder VPN.", @"El adaptador de red no se suspende: menos picos de ping. Solo adaptadores físicos, sin virtuales ni VPN.", @"O adaptador de rede não entra em suspensão — menos picos de ping. Só adaptadores físicos, sem virtuais nem VPN.", @"Ağ bağdaştırıcısı uyku moduna geçmez — daha az ping sıçraması. Yalnızca fiziksel bağdaştırıcılar; sanal ve VPN hariç.", @"Karta sieciowa nie usypia — mniej skoków pingu. Tylko fizyczne karty, bez wirtualnych i VPN.");
            A("tw.p2p-off.t", @"Отключить раздачу обновлений другим ПК", @"Stop sharing updates with other PCs", @"Вимкнути роздачу оновлень іншим ПК", @"Update-Weitergabe an andere PCs beenden", @"Dejar de compartir actualizaciones con otros PC", @"Parar de compartilhar atualizações com outros PCs", @"Güncellemeleri diğer PC'lerle paylaşmayı durdur", @"Wyłącz udostępnianie aktualizacji innym komputerom");
            A("tw.p2p-off.d", @"Windows перестаёт отдавать обновления в интернет через ваш канал — канал свободнее во время игры.", @"Windows stops uploading updates to the internet over your connection — more bandwidth while you play.", @"Windows перестає віддавати оновлення в інтернет через ваш канал — канал вільніший під час гри.", @"Windows lädt keine Updates mehr über Ihre Leitung ins Internet hoch — mehr Bandbreite beim Spielen.", @"Windows deja de subir actualizaciones a internet con tu conexión: más ancho de banda mientras juegas.", @"O Windows para de enviar atualizações pela sua conexão — mais banda enquanto você joga.", @"Windows bağlantınız üzerinden internete güncelleme yüklemeyi bırakır — oynarken daha fazla bant genişliği.", @"Windows przestaje wysyłać aktualizacje przez twoje łącze — więcej przepustowości podczas gry.");
            A("tw.sys-resp.t", @"Приоритет активной программе", @"Priority for the active app", @"Пріоритет активній програмі", @"Vorrang für die aktive Anwendung", @"Prioridad para la aplicación activa", @"Prioridade para o aplicativo ativo", @"Etkin uygulamaya öncelik", @"Priorytet dla aktywnej aplikacji");
            A("tw.sys-resp.d", @"Резерв процессора под фоновые задачи уменьшается с 20 % до 10 % — больше времени игре и звуку.", @"The CPU share reserved for background tasks drops from 20% to 10% — more time for the game and audio.", @"Резерв процесора під фонові завдання зменшується з 20 % до 10 % — більше часу грі та звуку.", @"Der CPU-Anteil für Hintergrundaufgaben sinkt von 20 % auf 10 % — mehr Zeit für Spiel und Ton.", @"La reserva de CPU para tareas en segundo plano baja del 20 % al 10 %: más tiempo para el juego y el audio.", @"A reserva de CPU para tarefas em segundo plano cai de 20% para 10% — mais tempo para o jogo e o áudio.", @"Arka plan görevleri için ayrılan işlemci payı %20'den %10'a iner — oyun ve ses için daha fazla zaman.", @"Rezerwa procesora na zadania w tle spada z 20% do 10% — więcej czasu dla gry i dźwięku.");
            A("tw.menu-delay.t", @"Быстрые меню", @"Faster menus", @"Швидкі меню", @"Schnellere Menüs", @"Menús más rápidos", @"Menus mais rápidos", @"Daha hızlı menüler", @"Szybsze menu");
            A("tw.menu-delay.d", @"Подменю открываются через 0,1 с вместо 0,4 с — интерфейс заметно бодрее.", @"Submenus open after 0.1 s instead of 0.4 s — the interface feels much snappier.", @"Підменю відкриваються за 0,1 с замість 0,4 с — інтерфейс помітно жвавіший.", @"Untermenüs öffnen sich nach 0,1 s statt 0,4 s — die Oberfläche wirkt deutlich flotter.", @"Los submenús se abren a los 0,1 s en lugar de 0,4 s: la interfaz se nota más ágil.", @"Os submenus abrem em 0,1 s em vez de 0,4 s — a interface fica bem mais ágil.", @"Alt menüler 0,4 sn yerine 0,1 sn'de açılır — arayüz belirgin şekilde daha çevik.", @"Podmenu otwierają się po 0,1 s zamiast 0,4 s — interfejs jest wyraźnie żwawszy.");
            A("tw.animations.t", @"Отключить анимацию окон", @"Turn off window animations", @"Вимкнути анімацію вікон", @"Fensteranimationen ausschalten", @"Desactivar las animaciones de ventanas", @"Desligar animações de janelas", @"Pencere animasyonlarını kapat", @"Wyłącz animacje okien");
            A("tw.animations.d", @"Окна сворачиваются и разворачиваются мгновенно. Сглаживание шрифтов не трогается.", @"Windows minimize and restore instantly. Font smoothing is left untouched.", @"Вікна згортаються й розгортаються миттєво. Згладжування шрифтів не чіпається.", @"Fenster werden sofort minimiert und wiederhergestellt. Die Schriftglättung bleibt unverändert.", @"Las ventanas se minimizan y restauran al instante. El suavizado de fuentes no se toca.", @"As janelas minimizam e restauram na hora. A suavização de fontes não é alterada.", @"Pencereler anında küçülür ve geri gelir. Yazı tipi yumuşatma değişmez.", @"Okna minimalizują się i przywracają natychmiast. Wygładzanie czcionek pozostaje bez zmian.");
            A("tw.startup-delay.t", @"Убрать задержку автозагрузки", @"Remove the startup delay", @"Прибрати затримку автозавантаження", @"Autostart-Verzögerung entfernen", @"Quitar el retraso de inicio", @"Remover o atraso de inicialização", @"Başlangıç gecikmesini kaldır", @"Usuń opóźnienie autostartu");
            A("tw.startup-delay.d", @"Windows не ждёт несколько секунд перед запуском программ из автозагрузки — Discord и лаунчеры готовы раньше.", @"Windows doesn't wait a few seconds before launching startup apps — Discord and launchers are ready sooner.", @"Windows не чекає кілька секунд перед запуском програм з автозавантаження — Discord і лаунчери готові раніше.", @"Windows wartet nicht mehrere Sekunden, bevor Autostart-Apps starten — Discord und Launcher sind früher bereit.", @"Windows no espera unos segundos antes de abrir las aplicaciones de inicio: Discord y los launchers están listos antes.", @"O Windows não espera alguns segundos para abrir os aplicativos de inicialização — Discord e launchers ficam prontos antes.", @"Windows başlangıç uygulamalarını açmadan önce birkaç saniye beklemez — Discord ve başlatıcılar daha erken hazır olur.", @"Windows nie czeka kilku sekund przed uruchomieniem programów z autostartu — Discord i launchery są gotowe wcześniej.");
            A("tw.mouse-accel.t", @"Отключить ускорение мыши", @"Turn off mouse acceleration", @"Вимкнути прискорення миші", @"Mausbeschleunigung ausschalten", @"Desactivar la aceleración del ratón", @"Desligar a aceleração do mouse", @"Fare ivmesini kapat", @"Wyłącz przyspieszenie myszy");
            A("tw.mouse-accel.d", @"Снимает «Повышенную точность указателя»: курсор и прицел двигаются ровно столько, сколько мышь. Сначала может быть непривычно.", @"Turns off “Enhance pointer precision”: the cursor and crosshair move exactly as much as the mouse. It may feel unusual at first.", @"Знімає «Підвищену точність указівника»: курсор і приціл рухаються рівно стільки, скільки миша. Спочатку може бути незвично.", @"Deaktiviert „Zeigerbeschleunigung verbessern“: Cursor und Fadenkreuz bewegen sich genau so weit wie die Maus. Anfangs ungewohnt.", @"Desactiva «Mejorar la precisión del puntero»: el cursor y la mira se mueven exactamente lo que el ratón. Al principio puede resultar raro.", @"Desliga “Aprimorar precisão do ponteiro”: o cursor e a mira se movem exatamente o quanto o mouse. Pode parecer estranho no início.", @"“İşaretçi hassasiyetini artır”ı kapatır: imleç ve nişangâh tam olarak fare kadar hareket eder. Başta alışılmadık gelebilir.", @"Wyłącza „Zwiększ precyzję wskaźnika”: kursor i celownik poruszają się dokładnie tyle, co mysz. Na początku może być nietypowo.");
            A("tw.promo-apps.t", @"Запретить тихую установку рекламных приложений", @"Block silent installs of promoted apps", @"Заборонити тиху інсталяцію рекламних застосунків", @"Stille Installation beworbener Apps verhindern", @"Bloquear la instalación silenciosa de apps promocionadas", @"Bloquear instalação silenciosa de apps promovidos", @"Tanıtılan uygulamaların sessiz yüklenmesini engelle", @"Zablokuj ciche instalowanie promowanych aplikacji");
            A("tw.promo-apps.d", @"Windows перестаёт сама докачивать игры и рекламные приложения в меню «Пуск».", @"Windows stops downloading games and promoted apps into the Start menu on its own.", @"Windows перестає сама докачувати ігри та рекламні застосунки в меню «Пуск».", @"Windows lädt keine Spiele und beworbenen Apps mehr eigenständig ins Startmenü.", @"Windows deja de descargar por su cuenta juegos y apps promocionadas en el menú Inicio.", @"O Windows para de baixar sozinho jogos e apps promovidos no menu Iniciar.", @"Windows Başlat menüsüne kendi kendine oyun ve tanıtılan uygulama indirmeyi bırakır.", @"Windows przestaje samodzielnie pobierać gry i promowane aplikacje do menu Start.");
            A("tw.storage-sense.t", @"Включить контроль памяти Windows", @"Turn on Windows Storage Sense", @"Увімкнути контроль пам’яті Windows", @"Windows-Speicheroptimierung einschalten", @"Activar el Sensor de almacenamiento", @"Ativar o Sensor de Armazenamento", @"Windows Depolama Algısı'nı aç", @"Włącz Czujnik pamięci Windows");
            A("tw.storage-sense.d", @"Windows сама раз в неделю удаляет временные файлы. Настройку очистки папки «Загрузки» это не меняет.", @"Windows deletes temporary files on its own once a week. It doesn't change how the Downloads folder is cleaned.", @"Windows сама раз на тиждень видаляє тимчасові файли. Налаштування очищення папки «Завантаження» це не змінює.", @"Windows löscht temporäre Dateien einmal pro Woche selbst. Die Bereinigung des Download-Ordners bleibt unverändert.", @"Windows borra los archivos temporales una vez por semana. No cambia cómo se limpia la carpeta Descargas.", @"O Windows apaga arquivos temporários sozinho uma vez por semana. Não muda a limpeza da pasta Downloads.", @"Windows geçici dosyaları haftada bir kendisi siler. İndirilenler klasörünün temizlenme ayarı değişmez.", @"Windows sam usuwa pliki tymczasowe raz w tygodniu. Nie zmienia to czyszczenia folderu Pobrane.");

            A("det.plan", @"Схема питания", @"Power plan", @"Схема живлення", @"Energiesparplan", @"Plan de energía", @"Plano de energia", @"Güç planı", @"Plan zasilania");
            A("plan.balanced", @"Сбалансированная", @"Balanced", @"Збалансована", @"Ausbalanciert", @"Equilibrado", @"Equilibrado", @"Dengeli", @"Zrównoważony");
            A("plan.saver", @"Экономия энергии", @"Power saver", @"Економія енергії", @"Energiesparmodus", @"Economizador", @"Economia de energia", @"Güç tasarrufu", @"Oszczędzanie energii");
            A("plan.high", @"Высокая производительность", @"High performance", @"Висока продуктивність", @"Höchstleistung", @"Alto rendimiento", @"Alto desempenho", @"Yüksek performans", @"Wysoka wydajność");
            A("plan.ultimate", @"Максимальная производительность", @"Ultimate performance", @"Максимальна продуктивність", @"Ultimative Leistung", @"Máximo rendimiento", @"Desempenho máximo", @"Nihai performans", @"Najwyższa wydajność");
            A("plan.custom", @"своя схема", @"custom plan", @"власна схема", @"eigener Plan", @"plan personalizado", @"plano personalizado", @"özel plan", @"własny plan");
            A("plan.unknown", @"неизвестно", @"unknown", @"невідомо", @"unbekannt", @"desconocido", @"desconhecido", @"bilinmiyor", @"nieznany");

            // --- Очистка ---
            A("cl.title", @"Очистка", @"Cleanup", @"Очищення", @"Bereinigung", @"Limpieza", @"Limpeza", @"Temizlik", @"Czyszczenie");
            A("cl.sub", @"Удаляет кэш и временные файлы. Отмеченное по умолчанию безопасно; остальное — по желанию, с пояснениями.", @"Removes caches and temporary files. Items checked by default are safe; the rest is optional and explained.", @"Видаляє кеш і тимчасові файли. Позначене за замовчуванням безпечне; решта — за бажанням, з поясненнями.", @"Entfernt Caches und temporäre Dateien. Standardmäßig markierte Punkte sind sicher, der Rest ist optional und erklärt.", @"Elimina cachés y archivos temporales. Lo marcado por defecto es seguro; el resto es opcional y está explicado.", @"Remove caches e arquivos temporários. O que vem marcado é seguro; o resto é opcional e explicado.", @"Önbellekleri ve geçici dosyaları siler. Varsayılan olarak işaretliler güvenlidir; diğerleri isteğe bağlıdır ve açıklanmıştır.", @"Usuwa pamięć podręczną i pliki tymczasowe. Domyślnie zaznaczone jest bezpieczne; reszta jest opcjonalna i opisana.");
            A("cl.temp.t", @"Временные файлы", @"Temporary files", @"Тимчасові файли", @"Temporäre Dateien", @"Archivos temporales", @"Arquivos temporários", @"Geçici dosyalar", @"Pliki tymczasowe");
            A("cl.temp.d", @"Папка %TEMP% и Windows\Temp. Удаляются только файлы старше суток — то, что сейчас нужно программам, остаётся.", @"The %TEMP% folder and Windows\Temp. Only files older than a day are removed — anything programs need right now stays.", @"Папка %TEMP% і Windows\Temp. Видаляються лише файли, старші за добу — те, що зараз потрібне програмам, лишається.", @"Der Ordner %TEMP% und Windows\Temp. Nur Dateien älter als ein Tag werden entfernt — was Programme gerade brauchen, bleibt.", @"La carpeta %TEMP% y Windows\Temp. Solo se borran archivos de más de un día: lo que los programas usan ahora se queda.", @"A pasta %TEMP% e Windows\Temp. Só arquivos com mais de um dia são apagados — o que os programas usam agora fica.", @"%TEMP% klasörü ve Windows\Temp. Yalnızca bir günden eski dosyalar silinir — programların şu an ihtiyaç duyduğu dosyalar kalır.", @"Folder %TEMP% i Windows\Temp. Usuwane są tylko pliki starsze niż doba — to, czego programy teraz potrzebują, zostaje.");
            A("cl.browser.t", @"Кэш браузеров", @"Browser cache", @"Кеш браузерів", @"Browser-Cache", @"Caché de navegadores", @"Cache dos navegadores", @"Tarayıcı önbelleği", @"Pamięć podręczna przeglądarek");
            A("cl.browser.d", @"Chrome, Edge, Brave, Yandex, Vivaldi, Opera, Firefox. Только кэш — пароли, история и вход на сайты остаются.", @"Chrome, Edge, Brave, Yandex, Vivaldi, Opera, Firefox. Cache only — passwords, history and sign-ins stay.", @"Chrome, Edge, Brave, Yandex, Vivaldi, Opera, Firefox. Лише кеш — паролі, історія та вхід на сайти лишаються.", @"Chrome, Edge, Brave, Yandex, Vivaldi, Opera, Firefox. Nur der Cache — Passwörter, Verlauf und Anmeldungen bleiben.", @"Chrome, Edge, Brave, Yandex, Vivaldi, Opera, Firefox. Solo la caché: contraseñas, historial y sesiones se mantienen.", @"Chrome, Edge, Brave, Yandex, Vivaldi, Opera, Firefox. Só o cache — senhas, histórico e logins ficam.", @"Chrome, Edge, Brave, Yandex, Vivaldi, Opera, Firefox. Yalnızca önbellek — parolalar, geçmiş ve oturumlar kalır.", @"Chrome, Edge, Brave, Yandex, Vivaldi, Opera, Firefox. Tylko pamięć podręczna — hasła, historia i logowania zostają.");
            A("cl.browser.w", @"Закройте браузер: открытые браузеры пропускаются.", @"Close your browser: open browsers are skipped.", @"Закрийте браузер: відкриті браузери пропускаються.", @"Schließen Sie den Browser: geöffnete Browser werden übersprungen.", @"Cierra el navegador: los que estén abiertos se omiten.", @"Feche o navegador: navegadores abertos são ignorados.", @"Tarayıcıyı kapatın: açık tarayıcılar atlanır.", @"Zamknij przeglądarkę: otwarte przeglądarki są pomijane.");
            A("cl.dns.t", @"Сбросить кэш DNS", @"Flush the DNS cache", @"Скинути кеш DNS", @"DNS-Cache leeren", @"Vaciar la caché DNS", @"Limpar o cache de DNS", @"DNS önbelleğini temizle", @"Wyczyść pamięć DNS");
            A("cl.dns.d", @"Убирает устаревшие адреса сайтов и серверов — помогает, если игра или сайт не подключаются.", @"Clears outdated site and server addresses — helps when a game or site won't connect.", @"Прибирає застарілі адреси сайтів і серверів — допомагає, якщо гра чи сайт не підключаються.", @"Entfernt veraltete Adressen von Websites und Servern — hilft, wenn ein Spiel oder eine Seite keine Verbindung herstellt.", @"Quita direcciones antiguas de sitios y servidores: ayuda si un juego o web no conecta.", @"Remove endereços antigos de sites e servidores — ajuda quando um jogo ou site não conecta.", @"Eski site ve sunucu adreslerini temizler — bir oyun veya site bağlanmıyorsa yardımcı olur.", @"Usuwa nieaktualne adresy stron i serwerów — pomaga, gdy gra lub strona się nie łączy.");
            A("cl.recycle.t", @"Корзина", @"Recycle Bin", @"Кошик", @"Papierkorb", @"Papelera de reciclaje", @"Lixeira", @"Geri Dönüşüm Kutusu", @"Kosz");
            A("cl.recycle.d", @"Очищает корзину на всех дисках.", @"Empties the Recycle Bin on all drives.", @"Очищує кошик на всіх дисках.", @"Leert den Papierkorb auf allen Laufwerken.", @"Vacía la papelera en todos los discos.", @"Esvazia a lixeira em todos os discos.", @"Tüm sürücülerdeki Geri Dönüşüm Kutusu'nu boşaltır.", @"Opróżnia kosz na wszystkich dyskach.");
            A("cl.recycle.w", @"Удаление необратимо — перед очисткой программа спросит подтверждение.", @"This can't be undone — the tool asks for confirmation first.", @"Видалення незворотне — перед очищенням програма попросить підтвердження.", @"Nicht umkehrbar — das Programm fragt vorher nach.", @"Es irreversible: el programa pedirá confirmación antes.", @"Não dá para desfazer — o programa pede confirmação antes.", @"Geri alınamaz — program önce onay ister.", @"Tego nie da się cofnąć — program najpierw zapyta o potwierdzenie.");
            A("cl.shaders.t", @"Кэш шейдеров видеокарты", @"GPU shader cache", @"Кеш шейдерів відеокарти", @"Shader-Cache der Grafikkarte", @"Caché de sombreadores de la GPU", @"Cache de shaders da GPU", @"GPU gölgelendirici önbelleği", @"Pamięć podręczna shaderów GPU");
            A("cl.shaders.d", @"DirectX, NVIDIA, AMD, Intel. Нужен, если после смены драйвера в играх артефакты или вылеты.", @"DirectX, NVIDIA, AMD, Intel. Useful if games show artifacts or crash after a driver change.", @"DirectX, NVIDIA, AMD, Intel. Потрібен, якщо після зміни драйвера в іграх артефакти чи вильоти.", @"DirectX, NVIDIA, AMD, Intel. Sinnvoll, wenn Spiele nach einem Treiberwechsel Grafikfehler zeigen oder abstürzen.", @"DirectX, NVIDIA, AMD, Intel. Útil si tras cambiar de controlador los juegos muestran artefactos o se cierran.", @"DirectX, NVIDIA, AMD, Intel. Útil se após trocar o driver os jogos mostram artefatos ou fecham.", @"DirectX, NVIDIA, AMD, Intel. Sürücü değişikliğinden sonra oyunlarda bozulma veya çökme varsa işe yarar.", @"DirectX, NVIDIA, AMD, Intel. Przydaje się, gdy po zmianie sterownika gry mają artefakty lub się wysypują.");
            A("cl.shaders.w", @"Первый запуск игр после очистки будет с подлагиваниями, пока кэш соберётся заново.", @"The first launch of each game afterwards will stutter while the cache rebuilds.", @"Перший запуск ігор після очищення буде з підлагуваннями, поки кеш збереться знову.", @"Der erste Start jedes Spiels ruckelt danach, bis der Cache neu aufgebaut ist.", @"La primera vez que abras cada juego habrá tirones mientras se reconstruye la caché.", @"A primeira vez que abrir cada jogo terá engasgos enquanto o cache é refeito.", @"Sonrasında her oyunun ilk açılışı, önbellek yeniden oluşana kadar takılabilir.", @"Pierwsze uruchomienie każdej gry potem będzie przycinać, aż pamięć się odbuduje.");
            A("cl.thumbs.t", @"Кэш эскизов и значков", @"Thumbnail and icon cache", @"Кеш ескізів і значків", @"Miniatur- und Symbolcache", @"Caché de miniaturas e iconos", @"Cache de miniaturas e ícones", @"Küçük resim ve simge önbelleği", @"Pamięć miniatur i ikon");
            A("cl.thumbs.d", @"Помогает, если в Проводнике неправильные или «битые» значки. Проводник не перезапускается.", @"Helps if File Explorer shows wrong or broken icons. Explorer isn't restarted.", @"Допомагає, якщо в Провіднику неправильні чи «биті» значки. Провідник не перезапускається.", @"Hilft bei falschen oder defekten Symbolen im Explorer. Der Explorer wird nicht neu gestartet.", @"Ayuda si el Explorador muestra iconos erróneos o rotos. El Explorador no se reinicia.", @"Ajuda se o Explorador mostra ícones errados ou quebrados. O Explorador não é reiniciado.", @"Dosya Gezgini yanlış veya bozuk simgeler gösteriyorsa yardımcı olur. Gezgin yeniden başlatılmaz.", @"Pomaga, gdy Eksplorator pokazuje złe lub uszkodzone ikony. Eksplorator nie jest restartowany.");
            A("cl.wu.t", @"Кэш обновлений Windows", @"Windows Update cache", @"Кеш оновлень Windows", @"Windows Update-Cache", @"Caché de Windows Update", @"Cache do Windows Update", @"Windows Update önbelleği", @"Pamięć Windows Update");
            A("cl.wu.d", @"Скачанные установщики обновлений старше 10 дней.", @"Downloaded update installers older than 10 days.", @"Завантажені інсталятори оновлень, старші за 10 днів.", @"Heruntergeladene Update-Installer älter als 10 Tage.", @"Instaladores de actualizaciones descargados con más de 10 días.", @"Instaladores de atualizações baixados há mais de 10 dias.", @"10 günden eski indirilmiş güncelleme dosyaları.", @"Pobrane instalatory aktualizacji starsze niż 10 dni.");
            A("cl.wu.w", @"Если Windows ждёт перезагрузки после обновления, этот пункт пропускается.", @"Skipped if Windows is waiting for a restart after an update.", @"Якщо Windows чекає перезавантаження після оновлення, цей пункт пропускається.", @"Wird übersprungen, wenn Windows nach einem Update auf einen Neustart wartet.", @"Se omite si Windows espera un reinicio tras una actualización.", @"É ignorado se o Windows aguarda reinicialização após atualização.", @"Windows bir güncellemeden sonra yeniden başlatma bekliyorsa atlanır.", @"Pomijane, gdy Windows czeka na ponowne uruchomienie po aktualizacji.");
            A("cl.do.t", @"Кэш доставки обновлений", @"Delivery Optimization cache", @"Кеш доставки оновлень", @"Übermittlungsoptimierungs-Cache", @"Caché de Optimización de distribución", @"Cache da Otimização de Entrega", @"Teslim İyileştirme önbelleği", @"Pamięć optymalizacji dostarczania");
            A("cl.do.d", @"Части обновлений, которыми Windows делится с другими ПК. Скачаются снова, если понадобятся.", @"Update pieces Windows shares with other PCs. They're downloaded again if needed.", @"Частини оновлень, якими Windows ділиться з іншими ПК. Завантажаться знову, якщо знадобляться.", @"Update-Teile, die Windows mit anderen PCs teilt. Sie werden bei Bedarf neu geladen.", @"Partes de actualizaciones que Windows comparte con otros PC. Se volverán a descargar si hacen falta.", @"Partes de atualizações que o Windows compartilha com outros PCs. São baixadas de novo se precisar.", @"Windows'un diğer PC'lerle paylaştığı güncelleme parçaları. Gerekirse yeniden indirilir.", @"Fragmenty aktualizacji, które Windows udostępnia innym komputerom. W razie potrzeby pobiorą się ponownie.");
            A("cl.dumps.t", @"Отчёты об ошибках и дампы", @"Error reports and crash dumps", @"Звіти про помилки та дампи", @"Fehlerberichte und Absturzabbilder", @"Informes de errores y volcados", @"Relatórios de erro e despejos", @"Hata raporları ve döküm dosyaları", @"Raporty błędów i zrzuty pamięci");
            A("cl.dumps.d", @"Отчёты Windows о сбоях программ и дампы синих экранов.", @"Windows reports about app crashes and blue-screen dumps.", @"Звіти Windows про збої програм і дампи синіх екранів.", @"Windows-Berichte zu Programmabstürzen und Bluescreen-Abbilder.", @"Informes de Windows sobre fallos de programas y volcados de pantallazos azules.", @"Relatórios do Windows sobre falhas de programas e despejos de tela azul.", @"Program çökmeleriyle ilgili Windows raporları ve mavi ekran dökümleri.", @"Raporty Windows o awariach programów i zrzuty niebieskich ekranów.");
            A("cl.dumps.w", @"Дампы нужны, чтобы разобраться в причине синих экранов. Удаляйте, только если вылеты больше не беспокоят.", @"Dumps help find the cause of blue screens. Delete them only if crashes no longer bother you.", @"Дампи потрібні, щоб з’ясувати причину синіх екранів. Видаляйте, лише якщо вильоти більше не турбують.", @"Abbilder helfen, die Ursache von Bluescreens zu finden. Löschen Sie sie nur, wenn Abstürze kein Thema mehr sind.", @"Los volcados ayudan a encontrar la causa de los pantallazos azules. Bórralos solo si ya no tienes cierres.", @"Os despejos ajudam a achar a causa de telas azuis. Apague só se as falhas não incomodam mais.", @"Dökümler mavi ekranların nedenini bulmaya yarar. Yalnızca çökmeler artık sorun değilse silin.", @"Zrzuty pomagają znaleźć przyczynę niebieskich ekranów. Usuwaj je tylko, jeśli awarie już nie przeszkadzają.");
            A("cl.logs.t", @"Старые журналы Windows", @"Old Windows logs", @"Старі журнали Windows", @"Alte Windows-Protokolle", @"Registros antiguos de Windows", @"Logs antigos do Windows", @"Eski Windows günlükleri", @"Stare dzienniki Windows");
            A("cl.logs.d", @"Файлы журналов в Windows\Logs старше 30 дней.", @"Log files in Windows\Logs older than 30 days.", @"Файли журналів у Windows\Logs, старші за 30 днів.", @"Protokolldateien in Windows\Logs älter als 30 Tage.", @"Archivos de registro en Windows\Logs con más de 30 días.", @"Arquivos de log em Windows\Logs com mais de 30 dias.", @"Windows\Logs içindeki 30 günden eski günlük dosyaları.", @"Pliki dzienników w Windows\Logs starsze niż 30 dni.");
            A("cl.counting", @"Считаю размер…", @"Measuring…", @"Рахую розмір…", @"Größe wird ermittelt…", @"Calculando tamaño…", @"Calculando tamanho…", @"Boyut hesaplanıyor…", @"Liczę rozmiar…");
            A("cl.selected", @"Выбрано: {0}", @"Selected: {0}", @"Вибрано: {0}", @"Ausgewählt: {0}", @"Seleccionado: {0}", @"Selecionado: {0}", @"Seçilen: {0}", @"Wybrano: {0}");
            A("cl.run", @"Очистить выбранное", @"Clean selected", @"Очистити вибране", @"Auswahl bereinigen", @"Limpiar lo seleccionado", @"Limpar selecionados", @"Seçilenleri temizle", @"Wyczyść wybrane");
            A("cl.storageSense", @"Открыть «Контроль памяти» Windows", @"Open Windows Storage Sense", @"Відкрити «Контроль пам’яті» Windows", @"Windows-Speicheroptimierung öffnen", @"Abrir el Sensor de almacenamiento", @"Abrir o Sensor de Armazenamento", @"Windows Depolama Algısı'nı aç", @"Otwórz Czujnik pamięci Windows");
            A("cl.done", @"Освобождено {0}, занятых файлов пропущено: {1}.", @"Freed {0}; files in use skipped: {1}.", @"Звільнено {0}, зайнятих файлів пропущено: {1}.", @"{0} freigegeben; übersprungene Dateien in Verwendung: {1}.", @"Liberado {0}; archivos en uso omitidos: {1}.", @"Liberado {0}; arquivos em uso ignorados: {1}.", @"{0} boşaltıldı; kullanımdaki {1} dosya atlandı.", @"Zwolniono {0}; pominięto plików w użyciu: {1}.");
            A("cl.note.link", @"Папка {0} — это ссылка на другое место, её не трогаю.", @"{0} is a link to another location, so it was left alone.", @"Папка {0} — це посилання на інше місце, її не чіпаю.", @"{0} ist eine Verknüpfung an einen anderen Ort und bleibt unverändert.", @"{0} es un enlace a otra ubicación, así que no se toca.", @"{0} é um link para outro local e não foi alterado.", @"{0} başka bir konuma bağlantı olduğu için dokunulmadı.", @"{0} to łącze do innego miejsca — pozostawiono bez zmian.");
            A("cl.note.tempUnsafe", @"%TEMP% указывает на системную или личную папку — пропущено ради безопасности.", @"%TEMP% points to a system or personal folder — skipped for safety.", @"%TEMP% вказує на системну чи особисту папку — пропущено задля безпеки.", @"%TEMP% zeigt auf einen System- oder persönlichen Ordner — aus Sicherheitsgründen übersprungen.", @"%TEMP% apunta a una carpeta del sistema o personal: se omite por seguridad.", @"%TEMP% aponta para uma pasta do sistema ou pessoal — ignorado por segurança.", @"%TEMP% bir sistem veya kişisel klasörü gösteriyor — güvenlik için atlandı.", @"%TEMP% wskazuje na folder systemowy lub osobisty — pominięto dla bezpieczeństwa.");
            A("cl.note.winTempAdmin", @"Windows\Temp пропущена — для неё нужны права администратора.", @"Windows\Temp skipped — it needs administrator rights.", @"Windows\Temp пропущено — для неї потрібні права адміністратора.", @"Windows\Temp übersprungen — dafür sind Administratorrechte nötig.", @"Se omitió Windows\Temp: requiere permisos de administrador.", @"Windows\Temp ignorada — exige direitos de administrador.", @"Windows\Temp atlandı — yönetici izni gerekir.", @"Pominięto Windows\Temp — wymaga uprawnień administratora.");
            A("cl.note.browserOpen", @"Пропущены открытые браузеры: {0}.", @"Skipped open browsers: {0}.", @"Пропущено відкриті браузери: {0}.", @"Übersprungene geöffnete Browser: {0}.", @"Navegadores abiertos omitidos: {0}.", @"Navegadores abertos ignorados: {0}.", @"Atlanan açık tarayıcılar: {0}.", @"Pominięto otwarte przeglądarki: {0}.");
            A("cl.note.dnsOk", @"Кэш DNS сброшен.", @"DNS cache flushed.", @"Кеш DNS скинуто.", @"DNS-Cache geleert.", @"Caché DNS vaciada.", @"Cache de DNS limpo.", @"DNS önbelleği temizlendi.", @"Pamięć DNS wyczyszczona.");
            A("cl.note.dnsFail", @"Не удалось сбросить кэш DNS.", @"Couldn't flush the DNS cache.", @"Не вдалося скинути кеш DNS.", @"DNS-Cache konnte nicht geleert werden.", @"No se pudo vaciar la caché DNS.", @"Não foi possível limpar o cache de DNS.", @"DNS önbelleği temizlenemedi.", @"Nie udało się wyczyścić pamięci DNS.");
            A("cl.note.recycleFail", @"Не удалось очистить корзину.", @"Couldn't empty the Recycle Bin.", @"Не вдалося очистити кошик.", @"Papierkorb konnte nicht geleert werden.", @"No se pudo vaciar la papelera.", @"Não foi possível esvaziar a lixeira.", @"Geri Dönüşüm Kutusu boşaltılamadı.", @"Nie udało się opróżnić kosza.");
            A("cl.note.thumbsLocked", @"Часть баз занята Проводником — они очистятся после перезагрузки.", @"Some databases are in use by Explorer — they'll clear after a restart.", @"Частина баз зайнята Провідником — вони очистяться після перезавантаження.", @"Einige Datenbanken sind vom Explorer belegt — sie werden nach einem Neustart geleert.", @"Algunas bases las usa el Explorador: se limpiarán tras reiniciar.", @"Algumas bases estão em uso pelo Explorador — serão limpas após reiniciar.", @"Bazı veritabanları Gezgin tarafından kullanılıyor — yeniden başlatmadan sonra temizlenir.", @"Część baz jest używana przez Eksplorator — wyczyszczą się po restarcie.");
            A("cl.note.rebootPending", @"Windows ждёт перезагрузки после обновления — пропущено.", @"Windows is waiting for a restart after an update — skipped.", @"Windows чекає перезавантаження після оновлення — пропущено.", @"Windows wartet nach einem Update auf einen Neustart — übersprungen.", @"Windows espera un reinicio tras una actualización: se omite.", @"O Windows aguarda reinicialização após atualização — ignorado.", @"Windows bir güncellemeden sonra yeniden başlatma bekliyor — atlandı.", @"Windows czeka na restart po aktualizacji — pominięto.");

            // --- Журнал ---
            A("jr.title", @"Журнал", @"Activity log", @"Журнал", @"Protokoll", @"Registro", @"Registro", @"Günlük", @"Dziennik");
            A("jr.sub", @"Всё, что программа сделала, по времени. Хранится в файле log.txt.", @"Everything the tool did, in order. Stored in log.txt.", @"Усе, що зробила програма, за часом. Зберігається у файлі log.txt.", @"Alles, was das Programm getan hat, chronologisch. Gespeichert in log.txt.", @"Todo lo que hizo el programa, en orden. Se guarda en log.txt.", @"Tudo o que o programa fez, em ordem. Fica salvo em log.txt.", @"Programın yaptığı her şey, sırayla. log.txt dosyasında saklanır.", @"Wszystko, co zrobił program, chronologicznie. Zapisywane w log.txt.");
            A("jr.copy", @"Скопировать", @"Copy", @"Скопіювати", @"Kopieren", @"Copiar", @"Copiar", @"Kopyala", @"Kopiuj");
            A("jr.copied", @"Журнал скопирован.", @"Log copied.", @"Журнал скопійовано.", @"Protokoll kopiert.", @"Registro copiado.", @"Registro copiado.", @"Günlük kopyalandı.", @"Dziennik skopiowany.");
            A("jr.empty", @"Пока пусто — здесь появится всё, что сделает программа.", @"Nothing yet — everything the tool does will show up here.", @"Поки порожньо — тут з’явиться все, що зробить програма.", @"Noch leer — hier erscheint alles, was das Programm tut.", @"Aún vacío: aquí aparecerá todo lo que haga el programa.", @"Vazio por enquanto — tudo o que o programa fizer aparecerá aqui.", @"Henüz boş — programın yaptığı her şey burada görünecek.", @"Na razie pusto — pojawi się tu wszystko, co zrobi program.");

            // --- PRO ---
            A("pro.title", @"BUL$ Opti PRO", @"BUL$ Opti PRO", @"BUL$ Opti PRO", @"BUL$ Opti PRO", @"BUL$ Opti PRO", @"BUL$ Opti PRO", @"BUL$ Opti PRO", @"BUL$ Opti PRO");
            A("pro.sub", @"Отдельное платное приложение. Этот бесплатный мини-тул его не заменяет и не разблокирует.", @"A separate paid app. This free mini tool doesn't replace or unlock it.", @"Окремий платний застосунок. Цей безкоштовний міні-тул його не замінює й не розблоковує.", @"Eine separate kostenpflichtige App. Dieses kostenlose Mini-Tool ersetzt oder entsperrt sie nicht.", @"Una aplicación de pago aparte. Esta mini herramienta gratuita no la sustituye ni la desbloquea.", @"Um aplicativo pago à parte. Esta mini ferramenta gratuita não o substitui nem o desbloqueia.", @"Ayrı, ücretli bir uygulama. Bu ücretsiz mini araç onun yerini tutmaz ve kilidini açmaz.", @"Osobna, płatna aplikacja. To darmowe mini-narzędzie jej nie zastępuje ani nie odblokowuje.");
            A("pro.text", @"Мини-тул делает разовую базовую настройку. BUL$ Opti PRO работает глубже: подбирает настройки под ваше железо и игры, следит за системой в реальном времени и держит настройки после обновлений Windows.", @"The mini tool does a one-time basic setup. BUL$ Opti PRO goes deeper: it tunes settings for your hardware and games, monitors the system in real time and keeps your settings after Windows updates.", @"Міні-тул робить разове базове налаштування. BUL$ Opti PRO працює глибше: підбирає налаштування під ваше залізо та ігри, стежить за системою в реальному часі й тримає налаштування після оновлень Windows.", @"Das Mini-Tool nimmt eine einmalige Grundeinrichtung vor. BUL$ Opti PRO geht tiefer: Es passt Einstellungen an Ihre Hardware und Spiele an, überwacht das System in Echtzeit und hält Ihre Einstellungen nach Windows-Updates.", @"La mini herramienta hace un ajuste básico único. BUL$ Opti PRO va más allá: adapta los ajustes a tu hardware y juegos, vigila el sistema en tiempo real y mantiene la configuración tras las actualizaciones de Windows.", @"A mini ferramenta faz um ajuste básico único. O BUL$ Opti PRO vai além: adapta as configurações ao seu hardware e jogos, monitora o sistema em tempo real e mantém tudo após atualizações do Windows.", @"Mini araç tek seferlik temel bir ayar yapar. BUL$ Opti PRO daha derine iner: ayarları donanımınıza ve oyunlarınıza göre seçer, sistemi gerçek zamanlı izler ve Windows güncellemelerinden sonra ayarlarınızı korur.", @"Mini-narzędzie wykonuje jednorazową podstawową konfigurację. BUL$ Opti PRO idzie dalej: dobiera ustawienia do twojego sprzętu i gier, monitoruje system na żywo i utrzymuje ustawienia po aktualizacjach Windows.");
            A("pro.tools", @"Что внутри", @"What's inside", @"Що всередині", @"Was enthalten ist", @"Qué incluye", @"O que inclui", @"İçinde neler var", @"Co zawiera");
            A("pro.t1", @"ИИ-оптимизация", @"AI optimization", @"ШІ-оптимізація", @"KI-Optimierung", @"Optimización con IA", @"Otimização com IA", @"Yapay zekâ optimizasyonu", @"Optymalizacja AI");
            A("pro.t1.d", @"Анализирует систему и советует точечно под ваше железо.", @"Analyzes your system and gives advice tailored to your hardware.", @"Аналізує систему й радить точково під ваше залізо.", @"Analysiert Ihr System und gibt Tipps passend zu Ihrer Hardware.", @"Analiza tu sistema y aconseja según tu hardware.", @"Analisa o sistema e dá dicas sob medida para o seu hardware.", @"Sisteminizi analiz eder ve donanımınıza özel öneriler verir.", @"Analizuje system i doradza pod twój sprzęt.");
            A("pro.t2", @"BIOS-анализатор", @"BIOS analyzer", @"BIOS-аналізатор", @"BIOS-Analyse", @"Analizador de BIOS", @"Analisador de BIOS", @"BIOS analizörü", @"Analizator BIOS");
            A("pro.t2.d", @"80+ настроек BIOS с точными значениями и путями в меню.", @"80+ BIOS settings with exact values and menu paths.", @"80+ налаштувань BIOS з точними значеннями й шляхами в меню.", @"Über 80 BIOS-Einstellungen mit genauen Werten und Menüpfaden.", @"Más de 80 ajustes de BIOS con valores exactos y rutas de menú.", @"Mais de 80 configurações de BIOS com valores exatos e caminhos de menu.", @"Kesin değerler ve menü yollarıyla 80'den fazla BIOS ayarı.", @"Ponad 80 ustawień BIOS z dokładnymi wartościami i ścieżkami w menu.");
            A("pro.t3", @"89 системных твиков", @"89 system tweaks", @"89 системних твіків", @"89 System-Tweaks", @"89 ajustes del sistema", @"89 ajustes de sistema", @"89 sistem ayarı", @"89 poprawek systemu");
            A("pro.t3.d", @"У каждого — пометка «безопасно» или «осторожно».", @"Each marked as safe or caution.", @"У кожного — позначка «безпечно» чи «обережно».", @"Jeder als sicher oder mit Vorsicht markiert.", @"Cada uno marcado como seguro o con precaución.", @"Cada um marcado como seguro ou com cautela.", @"Her biri güvenli veya dikkatli olarak işaretli.", @"Każda oznaczona jako bezpieczna lub ostrożnie.");
            A("pro.t4", @"Профили под игры", @"Game profiles", @"Профілі під ігри", @"Spielprofile", @"Perfiles por juego", @"Perfis por jogo", @"Oyun profilleri", @"Profile gier");
            A("pro.t4.d", @"CS2, Rust, Valorant, Apex, Fortnite, Tarkov и другие.", @"CS2, Rust, Valorant, Apex, Fortnite, Tarkov and more.", @"CS2, Rust, Valorant, Apex, Fortnite, Tarkov та інші.", @"CS2, Rust, Valorant, Apex, Fortnite, Tarkov und mehr.", @"CS2, Rust, Valorant, Apex, Fortnite, Tarkov y más.", @"CS2, Rust, Valorant, Apex, Fortnite, Tarkov e outros.", @"CS2, Rust, Valorant, Apex, Fortnite, Tarkov ve daha fazlası.", @"CS2, Rust, Valorant, Apex, Fortnite, Tarkov i inne.");
            A("pro.t5", @"Раскладка ядер", @"Core affinity", @"Розкладка ядер", @"Kernzuweisung", @"Afinidad de núcleos", @"Afinidade de núcleos", @"Çekirdek ataması", @"Przypisanie rdzeni");
            A("pro.t5.d", @"Умная привязка под гибридные процессоры, чиплеты и X3D-кэш.", @"Smart affinity for hybrid CPUs, chiplets and X3D cache.", @"Розумна прив’язка під гібридні процесори, чиплети та X3D-кеш.", @"Intelligente Zuweisung für Hybrid-CPUs, Chiplets und X3D-Cache.", @"Afinidad inteligente para CPU híbridas, chiplets y caché X3D.", @"Afinidade inteligente para CPUs híbridas, chiplets e cache X3D.", @"Hibrit işlemciler, çipletler ve X3D önbellek için akıllı atama.", @"Inteligentne przypisanie dla procesorów hybrydowych, chipletów i pamięci X3D.");
            A("pro.t6", @"Бенчмарк", @"Benchmark", @"Бенчмарк", @"Benchmark", @"Benchmark", @"Benchmark", @"Kıyaslama", @"Benchmark");
            A("pro.t6.d", @"10 тестов процессора, памяти и диска — замер до и после.", @"10 CPU, memory and disk tests — measure before and after.", @"10 тестів процесора, пам’яті й диска — заміри до і після.", @"10 Tests für CPU, Speicher und Laufwerk — Messung vorher und nachher.", @"10 pruebas de CPU, memoria y disco: medición antes y después.", @"10 testes de CPU, memória e disco — medição antes e depois.", @"10 işlemci, bellek ve disk testi — öncesi ve sonrası ölçüm.", @"10 testów procesora, pamięci i dysku — pomiar przed i po.");
            A("pro.t7", @"Мониторинг в реальном времени", @"Real-time monitoring", @"Моніторинг у реальному часі", @"Echtzeit-Überwachung", @"Monitorización en tiempo real", @"Monitoramento em tempo real", @"Gerçek zamanlı izleme", @"Monitorowanie na żywo");
            A("pro.t7.d", @"Загрузка, температуры и графики прямо во время игры.", @"Load, temperatures and graphs while you play.", @"Навантаження, температури й графіки просто під час гри.", @"Auslastung, Temperaturen und Diagramme während des Spielens.", @"Carga, temperaturas y gráficos mientras juegas.", @"Carga, temperaturas e gráficos enquanto você joga.", @"Oynarken yük, sıcaklık ve grafikler.", @"Obciążenie, temperatury i wykresy podczas gry.");
            A("pro.t8", @"Обновление драйверов", @"Driver updates", @"Оновлення драйверів", @"Treiber-Updates", @"Actualización de controladores", @"Atualização de drivers", @"Sürücü güncellemeleri", @"Aktualizacja sterowników");
            A("pro.t8.d", @"Проверяет и обновляет из проверенных источников.", @"Checks and updates from verified sources.", @"Перевіряє й оновлює з перевірених джерел.", @"Prüft und aktualisiert aus verifizierten Quellen.", @"Comprueba y actualiza desde fuentes verificadas.", @"Verifica e atualiza de fontes confiáveis.", @"Doğrulanmış kaynaklardan denetler ve günceller.", @"Sprawdza i aktualizuje ze zweryfikowanych źródeł.");
            A("pro.t9", @"Глубокая очистка", @"Deep cleanup", @"Глибоке очищення", @"Tiefenbereinigung", @"Limpieza profunda", @"Limpeza profunda", @"Derin temizlik", @"Głębokie czyszczenie");
            A("pro.t9.d", @"Кэш и мусор по всей системе.", @"Caches and junk across the whole system.", @"Кеш і сміття по всій системі.", @"Caches und Datenmüll im gesamten System.", @"Cachés y basura en todo el sistema.", @"Caches e lixo em todo o sistema.", @"Tüm sistemdeki önbellek ve gereksiz dosyalar.", @"Pamięć podręczna i śmieci w całym systemie.");
            A("pro.t10", @"Бэкап и откат", @"Backup and rollback", @"Бекап і відкат", @"Sicherung und Rückgängig", @"Copia y reversión", @"Backup e reversão", @"Yedekleme ve geri alma", @"Kopia i przywracanie");
            A("pro.t10.d", @"Точка восстановления перед изменениями — всё обратимо.", @"A restore point before changes — everything is reversible.", @"Точка відновлення перед змінами — усе зворотне.", @"Wiederherstellungspunkt vor Änderungen — alles umkehrbar.", @"Punto de restauración antes de cambios: todo es reversible.", @"Ponto de restauração antes das alterações — tudo é reversível.", @"Değişikliklerden önce geri yükleme noktası — her şey geri alınabilir.", @"Punkt przywracania przed zmianami — wszystko odwracalne.");
            A("pro.price", @"Разовый ключ от $9.99, без подписки и автосписаний. 30 дней на возврат.", @"One-time key from $9.99, no subscription or auto-renewal. 30-day refund.", @"Разовий ключ від $9.99, без підписки й автосписань. 30 днів на повернення.", @"Einmaliger Schlüssel ab 9,99 $, ohne Abo und automatische Verlängerung. 30 Tage Rückgabe.", @"Clave única desde 9,99 $, sin suscripción ni renovación automática. 30 días de reembolso.", @"Chave única a partir de US$ 9,99, sem assinatura nem renovação automática. 30 dias para reembolso.", @"9,99 $'dan başlayan tek seferlik anahtar; abonelik ve otomatik yenileme yok. 30 gün iade.", @"Jednorazowy klucz od 9,99 $, bez subskrypcji i automatycznego odnawiania. 30 dni na zwrot.");
            A("pro.open", @"Подробнее на bulsopti.com", @"Learn more on bulsopti.com", @"Детальніше на bulsopti.com", @"Mehr auf bulsopti.com", @"Más en bulsopti.com", @"Saiba mais em bulsopti.com", @"bulsopti.com'da daha fazlası", @"Więcej na bulsopti.com");
            A("pro.note", @"Откроется в браузере.", @"Opens in your browser.", @"Відкриється в браузері.", @"Öffnet sich im Browser.", @"Se abrirá en el navegador.", @"Abre no navegador.", @"Tarayıcıda açılır.", @"Otworzy się w przeglądarce.");

            // --- О программе ---
            A("ab.title", @"О программе", @"About", @"Про програму", @"Über das Programm", @"Acerca de", @"Sobre", @"Hakkında", @"O programie");
            A("ab.sub", @"Что это, кто сделал и что программа делает с системой.", @"What this is, who made it, and what it does to your system.", @"Що це, хто зробив і що програма робить із системою.", @"Was es ist, wer es gemacht hat und was es mit Ihrem System macht.", @"Qué es, quién lo hizo y qué hace con tu sistema.", @"O que é, quem fez e o que ele faz com o sistema.", @"Nedir, kim yaptı ve sisteminizde ne yapar.", @"Co to jest, kto to zrobił i co robi z systemem.");
            A("ab.version", @"Версия", @"Version", @"Версія", @"Version", @"Versión", @"Versão", @"Sürüm", @"Wersja");
            A("ab.publisher", @"Издатель", @"Publisher", @"Видавець", @"Herausgeber", @"Editor", @"Editora", @"Yayıncı", @"Wydawca");
            A("ab.license", @"Лицензия", @"License", @"Ліцензія", @"Lizenz", @"Licencia", @"Licença", @"Lisans", @"Licencja");
            A("ab.mode", @"Режим", @"Mode", @"Режим", @"Modus", @"Modo", @"Modo", @"Mod", @"Tryb");
            A("ab.source", @"Открытый исходный код", @"Open source code", @"Відкритий вихідний код", @"Offener Quellcode", @"Código abierto", @"Código aberto", @"Açık kaynak kodu", @"Otwarty kod źródłowy");
            A("ab.does", @"Что программа делает и чего не делает", @"What the tool does and doesn't do", @"Що програма робить і чого не робить", @"Was das Programm tut und was nicht", @"Qué hace y qué no hace", @"O que faz e o que não faz", @"Ne yapar, ne yapmaz", @"Co program robi, a czego nie");
            A("ab.does1", @"Меняет только настройки из раздела «Настройка» и удаляет только отмеченное в «Очистке».", @"Changes only the settings in Tweaks and deletes only what you check in Cleanup.", @"Змінює лише налаштування з розділу «Налаштування» і видаляє лише позначене в «Очищенні».", @"Ändert nur die Einstellungen unter „Einstellungen“ und löscht nur, was Sie unter „Bereinigung“ markieren.", @"Solo cambia los ajustes de «Ajustes» y solo borra lo que marques en «Limpieza».", @"Altera só as configurações de “Ajustes” e apaga só o que você marcar em “Limpeza”.", @"Yalnızca Ayarlar'daki ayarları değiştirir ve Temizlik'te işaretlediklerinizi siler.", @"Zmienia tylko ustawienia z sekcji „Ustawienia” i usuwa tylko to, co zaznaczysz w „Czyszczeniu”.");
            A("ab.does2", @"Перед каждым изменением запоминает прежнее значение — «Вернуть всё» восстанавливает его.", @"Saves the previous value before every change — “Undo all” restores it.", @"Перед кожною зміною запам’ятовує попереднє значення — «Повернути все» відновлює його.", @"Speichert vor jeder Änderung den vorherigen Wert — „Alles zurücksetzen“ stellt ihn wieder her.", @"Guarda el valor anterior antes de cada cambio: «Deshacer todo» lo restaura.", @"Guarda o valor anterior antes de cada alteração — “Desfazer tudo” o restaura.", @"Her değişiklikten önce önceki değeri kaydeder — “Tümünü geri al” onu geri yükler.", @"Przed każdą zmianą zapamiętuje poprzednią wartość — „Cofnij wszystko” ją przywraca.");
            A("ab.does3", @"Не отправляет данные в сеть, не ставит службы и задачи и не запускается вместе с Windows.", @"Doesn't send data over the network, install services or tasks, or start with Windows.", @"Не надсилає дані в мережу, не ставить служби й завдання і не запускається разом із Windows.", @"Sendet keine Daten übers Netz, installiert keine Dienste oder Aufgaben und startet nicht mit Windows.", @"No envía datos por la red, no instala servicios ni tareas y no se inicia con Windows.", @"Não envia dados pela rede, não instala serviços nem tarefas e não inicia com o Windows.", @"Ağ üzerinden veri göndermez, hizmet veya görev kurmaz ve Windows ile başlamaz.", @"Nie wysyła danych przez sieć, nie instaluje usług ani zadań i nie uruchamia się z Windows.");
            A("ab.does4", @"Права администратора спрашивает только для изменений, которым они нужны.", @"Asks for administrator rights only for changes that need them.", @"Права адміністратора просить лише для змін, яким вони потрібні.", @"Fragt Administratorrechte nur für Änderungen an, die sie benötigen.", @"Solo pide permisos de administrador para los cambios que los necesitan.", @"Pede direitos de administrador só para alterações que precisam deles.", @"Yönetici iznini yalnızca buna ihtiyaç duyan değişiklikler için ister.", @"Prosi o uprawnienia administratora tylko dla zmian, które ich wymagają.");
            A("ab.does5", @"Не трогает Защитник, брандмауэр, обновления Windows, службы и файл подкачки.", @"Doesn't touch Defender, the firewall, Windows Update, services or the page file.", @"Не чіпає Захисник, брандмауер, оновлення Windows, служби та файл підкачки.", @"Lässt Defender, Firewall, Windows Update, Dienste und Auslagerungsdatei unverändert.", @"No toca Defender, el firewall, Windows Update, los servicios ni el archivo de paginación.", @"Não mexe no Defender, firewall, Windows Update, serviços nem arquivo de paginação.", @"Defender'a, güvenlik duvarına, Windows Update'e, hizmetlere ve disk belleği dosyasına dokunmaz.", @"Nie rusza Defendera, zapory, Windows Update, usług ani pliku stronicowania.");
            A("ab.files", @"Файлы программы", @"Program files", @"Файли програми", @"Programmdateien", @"Archivos del programa", @"Arquivos do programa", @"Program dosyaları", @"Pliki programu");
            A("ab.openFolder", @"Открыть папку", @"Open folder", @"Відкрити папку", @"Ordner öffnen", @"Abrir carpeta", @"Abrir pasta", @"Klasörü aç", @"Otwórz folder");
            A("ab.remove", @"Удалить следы программы", @"Remove the tool's data", @"Видалити сліди програми", @"Programmdaten entfernen", @"Eliminar los datos del programa", @"Remover os dados do programa", @"Programın verilerini kaldır", @"Usuń dane programu");
            A("ab.removeText", @"Будут удалены журнал, настройки программы и счётчик. Изменения в системе это не отменяет — для этого есть «Вернуть всё».", @"The log, the tool's settings and the counter will be deleted. This doesn't undo system changes — use “Undo all” for that.", @"Буде видалено журнал, налаштування програми й лічильник. Зміни в системі це не скасовує — для цього є «Повернути все».", @"Protokoll, Programmeinstellungen und Zähler werden gelöscht. Systemänderungen werden dadurch nicht rückgängig gemacht — dafür gibt es „Alles zurücksetzen“.", @"Se borrarán el registro, los ajustes del programa y el contador. No deshace los cambios del sistema: para eso está «Deshacer todo».", @"O registro, as configurações do programa e o contador serão apagados. Isso não desfaz as alterações do sistema — para isso existe “Desfazer tudo”.", @"Günlük, program ayarları ve sayaç silinecek. Bu, sistem değişikliklerini geri almaz — bunun için “Tümünü geri al” var.", @"Zostaną usunięte dziennik, ustawienia programu i licznik. To nie cofa zmian w systemie — do tego służy „Cofnij wszystko”.");
            A("ab.removeYes", @"Удалить", @"Delete", @"Видалити", @"Löschen", @"Eliminar", @"Apagar", @"Sil", @"Usuń");
            A("ab.removed", @"Данные программы удалены.", @"The tool's data was removed.", @"Дані програми видалено.", @"Programmdaten entfernt.", @"Datos del programa eliminados.", @"Dados do programa removidos.", @"Program verileri kaldırıldı.", @"Dane programu usunięte.");
            A("ab.removeNote", @"Удаляет журнал и настройки программы из %LOCALAPPDATA% и реестра.", @"Removes the log and the tool's settings from %LOCALAPPDATA% and the registry.", @"Видаляє журнал і налаштування програми з %LOCALAPPDATA% та реєстру.", @"Entfernt Protokoll und Programmeinstellungen aus %LOCALAPPDATA% und der Registrierung.", @"Elimina el registro y los ajustes del programa de %LOCALAPPDATA% y del registro.", @"Remove o registro e as configurações do programa de %LOCALAPPDATA% e do Registro.", @"Günlüğü ve program ayarlarını %LOCALAPPDATA% ile kayıt defterinden kaldırır.", @"Usuwa dziennik i ustawienia programu z %LOCALAPPDATA% i rejestru.");
            A("ab.removeBlocked", @"Сначала верните изменения кнопкой «Вернуть всё» на «Обзоре» — иначе их будет нечем откатить.", @"First undo your changes with “Undo all” on Overview — otherwise there'd be nothing to roll them back with.", @"Спершу поверніть зміни кнопкою «Повернути все» в «Огляді» — інакше їх нічим буде відкотити.", @"Machen Sie zuerst Ihre Änderungen mit „Alles zurücksetzen“ in der Übersicht rückgängig — sonst lassen sie sich nicht mehr zurücknehmen.", @"Primero deshaz los cambios con «Deshacer todo» en Resumen; si no, no habrá forma de revertirlos.", @"Primeiro desfaça as alterações com “Desfazer tudo” na Visão geral — senão não haverá como revertê-las.", @"Önce Genel bakış'taki “Tümünü geri al” ile değişikliklerinizi geri alın — yoksa onları geri almanın yolu kalmaz.", @"Najpierw cofnij zmiany przyciskiem „Cofnij wszystko” w Przeglądzie — inaczej nie będzie czym ich wycofać.");

            // --- Диалоги ---
            A("dlg.cancel", @"Отмена", @"Cancel", @"Скасувати", @"Abbrechen", @"Cancelar", @"Cancelar", @"İptal", @"Anuluj");
            A("dlg.ok", @"Понятно", @"OK", @"Зрозуміло", @"OK", @"Entendido", @"OK", @"Tamam", @"OK");
            A("dlg.admin.title", @"Нужны права администратора", @"Administrator rights needed", @"Потрібні права адміністратора", @"Administratorrechte erforderlich", @"Se necesitan permisos de administrador", @"Direitos de administrador necessários", @"Yönetici izni gerekli", @"Wymagane uprawnienia administratora");
            A("dlg.admin.text", @"Windows разрешает эти изменения только с правами администратора:", @"Windows allows these changes only with administrator rights:", @"Windows дозволяє ці зміни лише з правами адміністратора:", @"Windows erlaubt diese Änderungen nur mit Administratorrechten:", @"Windows solo permite estos cambios con permisos de administrador:", @"O Windows só permite estas alterações com direitos de administrador:", @"Windows bu değişikliklere yalnızca yönetici izniyle izin verir:", @"Windows pozwala na te zmiany tylko z uprawnieniami administratora:");
            A("dlg.admin.note", @"Программа перезапустится с правами (Windows спросит подтверждение) и сразу продолжит — нажимать ещё раз не нужно.", @"The tool will restart with those rights (Windows will ask you to confirm) and carry on right away — no need to click again.", @"Програма перезапуститься з правами (Windows попросить підтвердження) і одразу продовжить — натискати ще раз не потрібно.", @"Das Programm startet mit diesen Rechten neu (Windows fragt nach Bestätigung) und macht sofort weiter — kein erneuter Klick nötig.", @"El programa se reiniciará con esos permisos (Windows pedirá confirmación) y continuará enseguida: no hace falta volver a pulsar.", @"O programa reiniciará com esses direitos (o Windows pedirá confirmação) e continuará na hora — não precisa clicar de novo.", @"Program bu izinlerle yeniden başlar (Windows onay ister) ve hemen devam eder — tekrar tıklamanıza gerek yok.", @"Program uruchomi się ponownie z uprawnieniami (Windows poprosi o potwierdzenie) i od razu będzie kontynuować — nie trzeba klikać drugi raz.");
            A("dlg.admin.yes", @"Продолжить с правами", @"Continue as administrator", @"Продовжити з правами", @"Als Administrator fortfahren", @"Continuar como administrador", @"Continuar como administrador", @"Yönetici olarak devam et", @"Kontynuuj jako administrator");
            A("dlg.admin.userOnly", @"Только без прав ({0})", @"Only without admin ({0})", @"Лише без прав ({0})", @"Nur ohne Adminrechte ({0})", @"Solo sin administrador ({0})", @"Só sem administrador ({0})", @"Yalnızca yöneticisiz ({0})", @"Tylko bez administratora ({0})");
            A("dlg.revert.title", @"Вернуть все изменения?", @"Undo all changes?", @"Повернути всі зміни?", @"Alle Änderungen zurücksetzen?", @"¿Deshacer todos los cambios?", @"Desfazer todas as alterações?", @"Tüm değişiklikler geri alınsın mı?", @"Cofnąć wszystkie zmiany?");
            A("dlg.revert.text", @"Программа вернёт прежние значения всех настроек, которые меняла, и ваши прежние обои.", @"The tool will restore the previous values of every setting it changed, and your previous wallpaper.", @"Програма поверне попередні значення всіх налаштувань, які змінювала, і ваші попередні шпалери.", @"Das Programm stellt die vorherigen Werte aller geänderten Einstellungen und Ihr bisheriges Hintergrundbild wieder her.", @"El programa restaurará los valores anteriores de todos los ajustes que cambió y tu fondo anterior.", @"O programa restaurará os valores anteriores de todas as configurações que alterou e seu papel de parede anterior.", @"Program değiştirdiği tüm ayarların önceki değerlerini ve önceki duvar kâğıdınızı geri yükler.", @"Program przywróci poprzednie wartości wszystkich zmienionych ustawień i twoją poprzednią tapetę.");
            A("dlg.revert.admin", @"Часть настроек системная — Windows спросит права администратора.", @"Some of these are system settings — Windows will ask for administrator rights.", @"Частина налаштувань системна — Windows попросить права адміністратора.", @"Einige davon sind Systemeinstellungen — Windows fragt nach Administratorrechten.", @"Algunos son ajustes del sistema: Windows pedirá permisos de administrador.", @"Algumas são configurações do sistema — o Windows pedirá direitos de administrador.", @"Bazıları sistem ayarı — Windows yönetici izni isteyecek.", @"Część to ustawienia systemowe — Windows poprosi o uprawnienia administratora.");
            A("dlg.revert.yes", @"Вернуть", @"Undo", @"Повернути", @"Zurücksetzen", @"Deshacer", @"Desfazer", @"Geri al", @"Cofnij");
            A("dlg.recycle.title", @"Очистить корзину?", @"Empty the Recycle Bin?", @"Очистити кошик?", @"Papierkorb leeren?", @"¿Vaciar la papelera?", @"Esvaziar a lixeira?", @"Geri Dönüşüm Kutusu boşaltılsın mı?", @"Opróżnić kosz?");
            A("dlg.recycle.text", @"В корзине объектов: {0} ({1}). Они будут удалены навсегда.", @"Items in the Recycle Bin: {0} ({1}). They'll be deleted permanently.", @"У кошику об’єктів: {0} ({1}). Їх буде видалено назавжди.", @"Elemente im Papierkorb: {0} ({1}). Sie werden endgültig gelöscht.", @"Elementos en la papelera: {0} ({1}). Se eliminarán para siempre.", @"Itens na lixeira: {0} ({1}). Eles serão apagados para sempre.", @"Geri Dönüşüm Kutusu'ndaki öğe sayısı: {0} ({1}). Kalıcı olarak silinecekler.", @"W koszu jest obiektów: {0} ({1}). Zostaną usunięte na zawsze.");
            A("dlg.recycle.yes", @"Очистить", @"Empty", @"Очистити", @"Leeren", @"Vaciar", @"Esvaziar", @"Boşalt", @"Opróżnij");
            A("dlg.error.title", @"Что-то пошло не так", @"Something went wrong", @"Щось пішло не так", @"Etwas ist schiefgelaufen", @"Algo salió mal", @"Algo deu errado", @"Bir şeyler ters gitti", @"Coś poszło nie tak");
            A("dlg.error.text", @"Программа поймала ошибку и продолжает работать. Подробности записаны в crash.log.", @"The tool caught an error and keeps running. Details are in crash.log.", @"Програма впіймала помилку й працює далі. Подробиці записано в crash.log.", @"Das Programm hat einen Fehler abgefangen und läuft weiter. Details stehen in crash.log.", @"El programa detectó un error y sigue funcionando. Los detalles están en crash.log.", @"O programa capturou um erro e continua funcionando. Detalhes em crash.log.", @"Program bir hata yakaladı ve çalışmaya devam ediyor. Ayrıntılar crash.log dosyasında.", @"Program wychwycił błąd i działa dalej. Szczegóły są w crash.log.");

